#!/usr/bin/env python3
# test_constants.py — the constants sweep. For every constant a binding
# exposes as `m.attr("NAME") = <C expression>;`, check the BUILT module's
# runtime (type, value) against what that same expression gives when
# compiled against the headers in this environment.
#
# Ground truth is an auto-generated "emitter" C++ TU per module — same
# non-Python #includes as the binding, same link libs as its .so per the
# root Jamfile — so the COMPILER is the oracle. Both sides of the diff run
# where the bindings were built.
#
# The m.attr lines are scanned in the binding's source PREPROCESSED with
# g++ -E (same includes as the build): #if resolved and macros expanded
# exactly as at the binding's build, so we sweep the lines the .so was
# actually built with (and a macro RHS is swept in its expanded form).
#
# Constant-shaped RHS = any C expression containing no function CALL:
# identifiers (`B_X`, `node_flavor::B_ANY_NODE`), literals (int, 0x, '4cc',
# "str"), casts (`(int)B_X`), and operator exprs (`1 << 30`, `A | B`).
# An RHS that calls anything (`py::cast(new BClipboard(...))`, a ctor,
# `py::int_(X)`) binds a computed value, not a header constant — out of
# scope. The RHS text is echoed verbatim into the emitter: it compiled in
# the binding's TU, so it compiles here (same includes).
#
# Note: module-level names set by `py::enum_(...).value()` (which
# pybind11 auto-exports to the module) are not m.attr lines and so not
# swept — where such a name ALSO has an m.attr line (InterfaceDefs
# B_USE_*), the int()-extractable enum instance compares as T.
#
# Per module:
#   emitter build+run  -> {name: (typeclass, value)}   T = integral, S = string,
#                                                       F = float/double,
#                                                       C = composite
#   Python child (the TSS-aware chunk/solo->closure harness)
#                    -> {name: (typeclass, value)}     T = int (incl. bool,
#                                                       pybind enums),
#                                                       S = str, F = float,
#                                                       C = other
#   diff (values compared numerically for T/F, typeclass-only for C)
#   -> one row `constants:<Module>`:
#     PASS "<n> ok"
#     FAIL "name: py (S,'x') != c++ (T,1); ..." (first 5)
#     FAIL "emitter build failed: ..."   (e.g. a name the headers lost)
#     FAIL "import failed (solo+closure): ..."
# Modules with no .so in the built package -> ABSENT "absent from built
# package (N constants)".
import json
import os
import re
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import common

CHILD = os.path.join(HERE, "child_constants.py")
# the suite usually runs from <repo>/tests/bindtests, but a standalone
# deployment (no repo alongside) must point PYAPI_REPO at the checkout:
REPO = os.environ.get("PYAPI_REPO",
                      os.path.dirname(os.path.dirname(HERE)))
JAMFILE = os.path.join(REPO, "Jamfile")
FARM = common.FARM
EMIT_DIR = os.path.join(common.SCRATCH, "emitters")
# installed Haiku headers (the compiler oracle's spec); overridable so the
# C++ side can also build against a haiku source checkout (e.g. on a Linux
# dev box, where the Python side stays the unrunnable "last mile"):
SYSTEM_HDRS = os.environ.get("BINDTESTS_SYSTEM_HDRS",
                             "/system/develop/headers")
CXX = os.environ.get("BINDTESTS_CXX", "g++")
JOBS = os.cpu_count() or 4

ATTR_RE = re.compile(r'^\s*m\.attr\("([A-Za-z_]\w*)"\)\s*=\s*([^;]+);')
INCLUDE_RE = re.compile(r"#\s*include\s*<([^>]+)>")
STRING_RE = re.compile(r'"[^"]*"')
CALL_RE = re.compile(r"[A-Za-z_]\w*\s*\(")     # identifier( = a call

EMITTER = """\
// GENERATED by test_constants.py — the constants emitter for module %s.
%s
#include <cstdio>
#include <type_traits>
#include <typeinfo>

// type-aware printing: the overload picked IS the C type class —
// T = any integral (enums via the SFINAE fwd), S = string,
// F = float/double (round-trip precision), C = composite (struct/
// class/pointer — value not comparable; the mangled typeid name is
// printed for diagnostics). Concrete overloads must precede the enum
// fwd (its body's call resolves at template definition, not
// instantiation); the catch-all is SFINAE-restricted to composites so
// every type has exactly one viable candidate (no ambiguity).
static void emit(const char* name, int v) { std::printf("%%s\\tT\\t%%d\\n", name, v); }
static void emit(const char* name, long v) { std::printf("%%s\\tT\\t%%ld\\n", name, v); }
static void emit(const char* name, long long v) { std::printf("%%s\\tT\\t%%lld\\n", name, v); }
static void emit(const char* name, unsigned v) { std::printf("%%s\\tT\\t%%u\\n", name, v); }
static void emit(const char* name, unsigned long v) { std::printf("%%s\\tT\\t%%lu\\n", name, v); }
static void emit(const char* name, unsigned long long v) { std::printf("%%s\\tT\\t%%llu\\n", name, v); }
static void emit(const char* name, const char* v) { std::printf("%%s\\tS\\t%%s\\n", name, v); }
static void emit(const char* name, float v) { std::printf("%%s\\tF\\t%%.17g\\n", name, (double)v); }
static void emit(const char* name, double v) { std::printf("%%s\\tF\\t%%.17g\\n", name, v); }
template <typename T>
typename std::enable_if<std::is_enum<T>::value>::type
emit(const char* name, T v) { emit(name, static_cast<int>(v)); }
template <typename T, typename = typename std::enable_if<
    !std::is_integral<T>::value && !std::is_enum<T>::value &&
    !std::is_floating_point<T>::value &&
    !std::is_same<T, const char*>::value>::type>
static void emit(const char* name, const T& v) { std::printf("%%s\\tC\\t%%s\\n", name, typeid(v).name()); }

int main()
{
%s
\treturn 0;
}
"""


def is_const_expr(rhs):
    """True if the m.attr RHS is a constant-shaped C expression (no call).
    A `(type)` cast never matches CALL_RE (an identifier is followed by `)`,
    not `(`), so no cast-stripping is needed — stripping it would hide real
    calls whose arg is a bare identifier (`py::int_(X)`)."""
    e = STRING_RE.sub('""', rhs)          # don't let call-shapes inside strings count
    return not CALL_RE.search(e)


def preprocess(src_p):
    """The binding's TU through g++ -E -P (same includes as the emitter):
    #if resolved and macros expanded exactly as at the binding's build, so
    the consts we sweep are the ones the .so was actually built with.
    -P suppresses the line markers -E would otherwise splice into the
    middle of any statement whose RHS is a macro from another file, keeping
    each m.attr on one line for ATTR_RE."""
    # pybind11 (the repo submodule) + the system Python headers, which the
    # emitter itself does not need (it never includes them)
    r = subprocess.run([CXX, "-std=c++14", "-E", "-P"]
                       + ["-I" + os.path.join(REPO, "pybind11", "include")]
                       + include_args() + [src_p],
                       capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError("preprocess failed: " + r.stderr[-500:])
    return r.stdout


def scan_modules():
    """-> {mod: {includes: [...], consts: {name: rhs}}} over the .cpp files
    jam builds (one level under each SEARCH_SOURCE dir — not os.walk, which
    would also sweep stale backups like bindings/support/old/)."""
    mods = {}
    for d in jam_search_source():
        dp = os.path.join(REPO, d)
        if not os.path.isdir(dp):
            continue
        for fn in sorted(os.listdir(dp)):
            if not fn.endswith(".cpp"):
                continue
            src_p = os.path.join(dp, fn)
            src = open(src_p, errors="replace").read()
            m = re.search(r"PYBIND11_MODULE\((\w+)", src)
            if not m:
                continue
            mod = m.group(1)
            # includes for the emitter come from the RAW source (gone after -E)
            includes = [h for h in INCLUDE_RE.findall(src)
                        if not h.startswith("pybind11/") and h != "Python.h"]
            consts = {}
            for line in preprocess(src_p).splitlines():
                am = ATTR_RE.match(line)
                if am and is_const_expr(am.group(2)):
                    consts[am.group(1)] = am.group(2).strip()  # last wins, as at runtime
            if consts:
                mods[mod] = {"includes": includes, "consts": consts}
    return mods


def _jam_tokens(text, header):
    """Tokens of the Jam block starting at the line beginning `header`, up to
    `;`, skipping `#` comments (Jamfile lists: SEARCH_SOURCE, sourceFiles…)."""
    toks, on = [], False
    for line in text.splitlines():
        s = line.strip()
        if not on:
            if s.startswith(header):
                on = True
            continue
        if s.startswith("#"):
            continue
        for t in s.split():
            if t == ";":
                return toks
            toks.append(t)
    return toks


def jam_search_source():
    """The Jamfile SEARCH_SOURCE dirs (relative to the repo root) — jam's
    build dirs. Scan only these, one level deep: a .cpp elsewhere (e.g. the
    stale bindings/support/old/*.cpp backups, which redeclare live module
    names and would clobber them) is not part of the build."""
    text = open(JAMFILE, errors="replace").read()
    return _jam_tokens(text, "SEARCH_SOURCE")


def jam_extra_libs():
    """Per-module link libs the emitter must reproduce. The Jamfile builds each
    module's .so as `LINKLIBS on <Mod>.so = $(LINKLIBS) -lX ...` — the base -lbe
    rides on $(LINKLIBS), and each module adds its own extras (-lmedia,
    -ltranslation, -lmail, -ltracker, ...). The emitter is a stand-in for that
    .so's build, so it must link the same extras to build under the same
    conditions as the module it is the oracle for. -> {mod: [X, ...]} (the
    extras only; the caller adds the base be)."""
    libs = {}
    for line in open(JAMFILE, errors="replace"):
        m = re.match(r"LINKLIBS on (\w+)\.so = (.+?);", line)
        if m:
            libs[m.group(1)] = re.findall(r"-l(\w+)", m.group(2))
    return libs


def include_args():
    # the repo's own headers (SubDirHdrs in the Jamfile), flat -I on each
    args = []
    for d in ("headers", "headers/app", "headers/interface"):
        p = os.path.join(REPO, d)
        if os.path.isdir(p):
            args.append("-I" + p)
    # Jambase puts every top-level subdir of the system headers on the path
    # (that's what makes flat `#include <StorageDefs.h>` work)
    args.append("-I" + SYSTEM_HDRS)
    for x in sorted(os.listdir(SYSTEM_HDRS)):
        p = os.path.join(SYSTEM_HDRS, x)
        if os.path.isdir(p):
            args.append("-I" + p)
    return args


def build_emitter(mod, info, extra_libs):
    os.makedirs(EMIT_DIR, exist_ok=True)
    src_p = os.path.join(EMIT_DIR, "emit_%s.cpp" % mod)
    bin_p = os.path.join(EMIT_DIR, "emit_%s" % mod)
    with open(src_p, "w") as f:
        f.write(EMITTER % (mod,
                           "\n".join("#include <%s>" % h
                                     for h in info["includes"]),
                           "\n".join('\temit("%s", %s);' % kv
                                    for kv in sorted(info["consts"].items()))))
    cmd = ([CXX, "-std=c++14", "-Wno-multichar"] + include_args()
           + [src_p, "-o", bin_p]
           + ["-l" + l for l in (["be"] + extra_libs.get(mod, []))])
    r = subprocess.run(cmd, capture_output=True, text=True)
    return (bin_p, None) if r.returncode == 0 else (None, r.stderr[-1500:])


def run_emitter(bin_p):
    """-> {name: (typeclass, value)} or raises."""
    out = subprocess.run([bin_p], capture_output=True, text=True,
                         timeout=60).stdout
    vals = {}
    for line in out.splitlines():
        name, tc, v = line.split("\t", 2)
        vals[name] = (tc, v)
    return vals


def _eq(c, p):
    """value equality within a matching typeclass: numeric for T/F
    (the two sides' textual forms differ: C %d/%%.17g vs Python str/repr),
    exact string for S, typeclass-only for C (composites aren't comparable)."""
    if c[0] not in "TSF":
        return True
    if c[0] == "T":
        return int(c[1]) == int(p[1])
    if c[0] == "F":
        return float(c[1]) == float(p[1])
    return c[1] == p[1]


def diff_module(mod, cxx, py, names):
    bad = []
    for n in names:
        c, p = cxx.get(n), py.get(n)
        if p is None:
            bad.append("%s: missing at runtime" % n)
        elif c[0] != p[0]:
            bad.append("%s: py (%s,%s) != c++ (%s,%s)"
                       % (n, p[0], p[1], c[0], c[1]))
        elif not _eq(c, p):
            bad.append("%s: py %s != c++ %s" % (n, p[1], c[1]))
    return bad


def main():
    mods = scan_modules()
    extra_libs = jam_extra_libs()
    present, absent = [], []
    for mod in sorted(mods):
        (present if os.path.isfile(os.path.join(FARM, mod + ".so"))
         else absent).append(mod)
    for mod in absent:
        common.absent("constants:%s" % mod,
                      "absent from built package (%d constants)"
                      % len(mods[mod]["consts"]))

    # build + run the emitters (parallel; a failure is a per-module finding)
    ok = {}
    with ThreadPoolExecutor(JOBS) as ex:
        for mod, (bin_p, err) in zip(present,
                                     ex.map(lambda m: build_emitter(m, mods[m], extra_libs),
                                            present)):
            if err is not None:
                common.fail("constants:%s" % mod,
                            "emitter build failed: " + err)
                continue
            try:
                ok[mod] = run_emitter(bin_p)
            except Exception as e:
                common.fail("constants:%s" % mod,
                            "emitter run failed: %s: %s" % (type(e).__name__, e))
    names_by_mod = {m: list(mods[m]["consts"]) for m in ok}

    # the Python side: same TSS-aware strategy as before (chunk when the
    # union closure fits the pool, else solo->closure per module)
    py_vals = {}
    if ok:
        union = common.closure(*ok)
        strat = common.import_strategy(union)
        print("strategy: %s (union=%d modules, %d with constants)"
              % (strat, len(union), len(ok)))
        done = set()
        if strat == "single":
            p = subprocess.run([sys.executable, CHILD, "chunk",
                                json.dumps(union), json.dumps(names_by_mod)],
                               cwd="/", capture_output=True, text=True,
                               timeout=900)
            line = [l for l in p.stdout.splitlines() if l.startswith("JSON ")]
            if line:
                payload = json.loads(line[0][5:])
                for m, rows in payload["results"].items():
                    done.add(m)
                    py_vals[m] = {n: (tc, v) for n, tc, v in rows}
                rest = [m for m in ok if m not in done]
                if rest:
                    print("chunk stopped at %s -> per-module fallback for %d"
                          % (payload["failed_at"], len(rest)))
            else:
                rest = list(ok)
        else:
            rest = sorted(ok)
        for mod in rest:
            p = subprocess.run([sys.executable, CHILD, mod,
                                json.dumps(names_by_mod[mod]), "solo"],
                               cwd="/", capture_output=True, text=True,
                               timeout=120)
            line = [l for l in p.stdout.splitlines() if l.startswith("JSON ")]
            if not line:
                p = subprocess.run([sys.executable, CHILD, mod,
                                    json.dumps(names_by_mod[mod]), "closure"],
                                   cwd="/", capture_output=True, text=True,
                                   timeout=120)
                line = [l for l in p.stdout.splitlines() if l.startswith("JSON ")]
            if not line:
                common.fail("constants:%s" % mod,
                            "import failed (solo+closure): "
                            + (p.stderr.strip().splitlines() or ["?"])[-1][:160])
                continue
            py_vals[mod] = {n: (tc, v) for n, tc, v in json.loads(line[0][5:])}

    for mod in sorted(ok):
        if mod not in py_vals:
            continue                     # already reported (import failed)
        bad = diff_module(mod, ok[mod], py_vals[mod], names_by_mod[mod])
        if bad:
            common.fail("constants:%s" % mod, "; ".join(bad[:5]))
        else:
            common.check("constants:%s" % mod,
                         lambda: "%d ok" % len(names_by_mod[mod]))

    sys.exit(common.report("test_constants"))


if __name__ == "__main__":
    main()
